fn has_only_one_distinct_element(a: &[i32]) -> bool {
    // If the slice is empty or has only one element, there can only be one distinct value.
    // Otherwise, compare every element to the first.
    if let Some((&first, rest)) = a.split_first() {
        rest.iter().all(|&x| x == first)
    } else {
        true
    }
}

